Btw, this was my test code, not yielding anything:

```
#include <stdio.h>
static gboolean
extcap_stdout_cb(GIOChannel *source, GIOCondition condition _U_, gpointer data)
{
    interface_options *interface_opts = (interface_options *)data;
    char buf[512];
    gsize bytes_read;

    /* Discard data to prevent child process hanging on stdout write */
    g_io_channel_read_chars(source, buf, sizeof(buf), &bytes_read, NULL);
    if (bytes_read == 0)
    {
        interface_opts->extcap_stdout_watch = 0;
        return G_SOURCE_REMOVE;
    }
    else
    {
        printf("Test: %s\n", buf);
        extcap_stdinfo_handler_invoke(EXTCAP_STDOUT, data, buf);
    }

    return G_SOURCE_CONTINUE;
}
```

extcap_stdinfo_handler_invoke is the hook to get the messages into Qt or any other app of the *shark family suite

